// n8n Code node: "Build AI request"
// Input: one row from the "Daily lane report" Postgres query (column `payload`).
// Output: the request body for the Claude Messages API + data the next nodes need.
let payload = $input.first().json.payload;
if (typeof payload === 'string') payload = JSON.parse(payload);
const cfg = $('Config').first().json;

// Only send Claude what it needs to explain: flagged items + context. `all_lanes` stays out.
const claude_input = {
  report_date: payload.report_date,
  baseline_window: payload.baseline_window,
  targets: payload.targets,
  network: payload.network,
  lanes_flagged: payload.lanes_flagged,
  hubs_flagged: payload.hubs_flagged,
  recurring_patterns: payload.recurring_patterns,
};
const has_flags = payload.lanes_flagged.length + payload.hubs_flagged.length > 0;

// Kept in prompts/system_prompt.md; injected here by build_workflow.py
const SYSTEM_PROMPT = "You are a logistics performance analyst for a parcel delivery network in Thailand. Every morning you receive yesterday's lane and hub KPIs as JSON. Lanes and hubs in it have ALREADY been flagged by statistical rules; your job is to explain them to an operations manager who has two minutes.

## How to analyse
1. Group flagged items by ROOT CAUSE, not by lane. If several lanes share a hub whose processing time is up, that is ONE hub issue affecting those lanes, not separate lane issues.
2. For each issue, locate where it happens using the evidence:
   - time_breakdown_h tells you WHERE time is lost (origin hub, linehaul, destination hub).
   - fail_reasons_first_attempt tells you WHY attempts fail (compare today_share_pct with baseline_share_pct).
   - first_attempt_fail_rate_by_time tells you WHEN they fail (compare today_fail_pct with baseline_fail_pct per slot).
   - trend_14d / dwell_p50_trend_14d tell you whether it is a one-day blip or a building trend.
3. Watch for hidden problems: if final_delivered_rate_pct looks healthy but first_attempt_success_pct dropped and attempts_per_parcel rose, the network is recovering parcels through costly re-attempts. Say so explicitly; a dashboard showing only final delivered rate would miss it.
4. recurring_patterns are known weekly patterns. Mention them only in the watchlist, never as today's incident.
5. Say what the data supports. If the evidence points to a cause but cannot prove it (for example, "address_issue" failures rose but we cannot see why), say "likely" and set confidence accordingly. Suggest what to check, not what you guess happened.

## Plain language
- Write for an operations manager, not an engineer. NEVER use JSON field names or snake_case words in your text: write "on-time rate", not "lead_time_compliance_pct"; "median hub processing time", not "dwell_p50_h"; "first-attempt success", not "first_attempt_success_pct".
- Write fail reasons in plain words too ("wrong or incomplete address", not "address_issue"; "customer not home", not "customer_not_available").
- control_metric must read like a sentence a manager would say, e.g. "KKC inbound processing back under 10h for 3 days".

## Strict rules about numbers
- Only use numbers that appear in the input JSON, exactly as written (you may drop the minus sign when you write "dropped by"). Percentages are already in percent.
- Do NOT calculate new numbers: no ratios ("4x slower"), sums, averages or differences that are not already in the data. Use the provided *_delta_pp fields for changes.
- Do not write dates other than the report_date. Refer to time slots by their names (morning, afternoon 12-17, evening).
- Your output is automatically checked; any number not found in the input causes the whole summary to be rejected.

## Output
Return ONLY a JSON object, no markdown fences, with this shape:
{
  "headline": "one sentence, the single most important thing today",
  "issues": [
    {
      "title": "max 8 words",
      "one_liner": "max 15 words in plain language a manager understands instantly: what happened + the one key number vs normal, e.g. '<hub> parcels wait <X>h instead of <Y>h, so <N> lanes deliver late'",
      "scope": "hub | lane | network",
      "affected": ["lane or hub codes exactly as in the input"],
      "severity": "high | medium | low",
      "what_happened": "1 sentence, max 25 words, with the key numbers",
      "likely_cause": "1 sentence, max 25 words, grounded in the evidence fields",
      "evidence": ["2-3 facts, max 15 words each, with numbers from the input"],
      "confidence": "high | medium | low",
      "suggested_action": "one concrete next step, max 15 words, starting with a verb",
      "control_metric": "one metric + threshold to track daily, max 12 words"
    }
  ],
  "watchlist": ["0-3 short notes on recurring patterns or early signals"],
  "summary_th": "max 2 sentences in Thai for the regional team, same facts and numbers"
}
Keep every field short: these are read on a phone and shown in a dashboard table. Order issues by severity, then by number of lanes affected. Every flagged lane and hub must appear in at least one issue's "affected" list.
";

return [{
  json: {
    report_date: payload.report_date,
    payload,
    claude_input,
    has_flags,
    request_body: {
      model: cfg.ai_model,
      max_tokens: 3000,
      system: SYSTEM_PROMPT,
      messages: [{
        role: 'user',
        content: `Daily lane-health data for ${payload.report_date}. Explain the flagged lanes and hubs.

<data>
${JSON.stringify(claude_input)}
</data>`,
      }],
    },
  },
}];

// n8n Code node: "Validate & format"
// Runs after the Claude API call (that node is set to continue on error).
//  1. Parses Claude's JSON.
//  2. Hallucination check: every number Claude wrote must exist in the data it was given,
//     every lane code must be real, and every flagged lane/hub must be covered.
//  3. If anything fails (or the API errored), falls back to a rule-based summary so ops
//     still get a correct report, clearly labelled.
//  4. Formats one chat message (Discord markdown) + rows for Google Sheets + a run-log entry.
const req = $('Build AI request').first().json;
const payload = req.payload;
const resp = $input.first().json;

// ---------------------------------------------------------------- validation helpers
function collectNumbers(node, out) {
  if (node === null || node === undefined) return out;
  if (typeof node === 'number') out.push(Math.abs(node));
  else if (typeof node === 'string') (node.match(/\d+(?:\.\d+)?/g) || []).forEach(n => out.push(parseFloat(n)));
  else if (Array.isArray(node)) node.forEach(x => collectNumbers(x, out));
  else if (typeof node === 'object') Object.entries(node).forEach(([k, v]) => { collectNumbers(k, out); collectNumbers(v, out); });
  return out;
}
function numbersInText(text) {
  const clean = text.replace(/(\d),(?=\d{3}\b)/g, '$1');            // 1,401 -> 1401
  return (clean.match(/\d+(?:\.\d+)?/g) || []).map(Number);
}
function textOf(node) {
  if (node === null || node === undefined) return '';
  if (typeof node === 'string') return node + '\n';
  if (Array.isArray(node)) return node.map(textOf).join('');
  if (typeof node === 'object') return Object.values(node).map(textOf).join('');
  return String(node) + '\n';
}

function validate(ai) {
  const issues = [];
  if (!ai || typeof ai.headline !== 'string' || !Array.isArray(ai.issues)) {
    return { ok: false, issues: ['Output does not match the expected JSON shape'], checked: 0 };
  }
  if (req.has_flags && ai.issues.length === 0) issues.push('No issues returned although items were flagged');

  // (a) numbers: each must exist in the input (abs value, 0.05 tolerance, or a rounding of it)
  const allowed = collectNumbers(req.claude_input, []);
  const text = textOf(ai);
  const found = numbersInText(text);
  const unknown = [...new Set(found.filter(x => {
    if (Number.isInteger(x) && x <= 3) return false;                  // small counts ("2 lanes")
    return !allowed.some(a => Math.abs(x - a) < 0.051
      || (Number.isInteger(x) && (x === Math.round(a) || x === Math.floor(a))));
  }))];
  if (unknown.length) issues.push(`Numbers not in source data: ${unknown.slice(0, 8).join(' ')}`);

  // (b) lane codes must exist
  const knownLanes = new Set(payload.all_lanes.map(l => l.lane));
  const lanesMentioned = [...new Set(text.match(/\b[A-Z]{3}-[A-Z]{3}\b/g) || [])];
  const fakeLanes = lanesMentioned.filter(l => !knownLanes.has(l));
  if (fakeLanes.length) issues.push(`Unknown lanes: ${fakeLanes.join(' ')}`);

  // (c) coverage: every flagged lane and hub appears in some issue's "affected"
  const affected = new Set(ai.issues.flatMap(i => Array.isArray(i.affected) ? i.affected : []));
  const missing = [
    ...payload.lanes_flagged.map(l => l.lane),
    ...[...new Set(payload.hubs_flagged.map(h => h.hub_code))],
  ].filter(code => !affected.has(code));
  if (missing.length) issues.push(`Flagged but not explained: ${missing.join(' ')}`);

  return { ok: issues.length === 0, issues, checked: found.length };
}

// ---------------------------------------------------------------- rule-based fallback
function fallbackSummary(p) {
  const out = [];
  const lanesCovered = new Set();
  const hubs = {};
  p.hubs_flagged.forEach(h => { (hubs[h.hub_code] = hubs[h.hub_code] || []).push(h); });

  for (const [code, rows] of Object.entries(hubs)) {
    const lanesHit = p.lanes_flagged
      .filter(l => rows.some(r => r.lanes_through_hub.includes(l.lane)))
      .map(l => l.lane);
    lanesHit.forEach(l => lanesCovered.add(l));
    const parts = rows.map(r => `${r.flow} median ${r.dwell_p50_h}h (usual ${r.dwell_p50_same_weekday_baseline_h}h)`);
    out.push({
      title: `${rows[0].hub_name} processing slowdown`,
      scope: 'hub', affected: [code, ...lanesHit],
      severity: lanesHit.length >= 2 ? 'high' : 'medium',
      what_happened: `${rows[0].hub_name}: ${parts.join('; ')}.`,
      one_liner: `${rows[0].hub_name} parcels wait ${rows[0].dwell_p50_h}h instead of ${rows[0].dwell_p50_same_weekday_baseline_h}h`,
      likely_cause: 'Hub-level processing delay; rules cannot determine why.',
      evidence: parts, confidence: 'medium',
      suggested_action: `Check staffing, sorter capacity and backlog at ${code} today.`,
      control_metric: `${code} median processing time back under ${p.targets.hub_dwell_p50_max_h}h`,
    });
  }

  for (const l of p.lanes_flagged.filter(x => !lanesCovered.has(x.lane))) {
    const k = l.kpis;
    const facts = [];
    let cause = '';
    if (l.breaches.includes('first_attempt_success')) {
      facts.push(`First-attempt success ${k.first_attempt_success_pct}% vs ${k.first_attempt_success_baseline_pct}% baseline`);
      const r = (l.fail_reasons_first_attempt || []).slice()
        .sort((a, b) => (b.today_share_pct - b.baseline_share_pct) - (a.today_share_pct - a.baseline_share_pct))[0];
      const s = (l.first_attempt_fail_rate_by_time || []).slice()
        .sort((a, b) => (b.today_fail_pct - b.baseline_fail_pct) - (a.today_fail_pct - a.baseline_fail_pct))[0];
      if (r) { facts.push(`${r.reason} is ${r.today_share_pct}% of failures (baseline ${r.baseline_share_pct}%)`); cause += `Rise in ${r.reason} failures. `; }
      if (s) facts.push(`${s.slot.slice(2)} fail rate ${s.today_fail_pct}% (baseline ${s.baseline_fail_pct}%)`);
      if (k.final_delivered_rate_pct >= k.final_delivered_rate_baseline_pct - 1 && k.attempts_per_parcel > k.attempts_per_parcel_baseline) {
        facts.push(`Final delivered rate still ${k.final_delivered_rate_pct}% but attempts per parcel ${k.attempts_per_parcel} (baseline ${k.attempts_per_parcel_baseline})`);
        cause += 'Hidden by re-attempts. ';
      }
    }
    if (l.breaches.includes('lead_time_compliance')) {
      facts.push(`On-time ${k.lead_time_compliance_pct}% vs ${k.lead_time_compliance_baseline_pct}% baseline`);
      const t = l.time_breakdown_h;
      const legs = [['origin hub', t.origin_hub_dwell_p50_today, t.origin_hub_dwell_p50_baseline],
                    ['linehaul', t.linehaul_p50_today, t.linehaul_p50_baseline],
                    ['destination hub', t.dest_hub_dwell_p50_today, t.dest_hub_dwell_p50_baseline]]
        .filter(x => x[1] !== null && x[2] !== null)
        .sort((a, b) => (b[1] - b[2]) - (a[1] - a[2]));
      if (legs.length) { facts.push(`${legs[0][0]} median ${legs[0][1]}h (baseline ${legs[0][2]}h)`); cause += `Most added time at ${legs[0][0]}. `; }
    }
    out.push({
      title: `${l.lane}: ${l.breaches.join(' + ').replace(/_/g, ' ')}`,
      scope: 'lane', affected: [l.lane], severity: l.severity,
      what_happened: facts[0] + '.', one_liner: `${l.lane}: ${facts[0]}`, likely_cause: cause.trim() || 'Not determined by rules.',
      evidence: facts.slice(1), confidence: 'low',
      suggested_action: `Review ${l.lane} with the ${l.dest_hub} regional team.`,
      control_metric: l.breaches.includes('first_attempt_success')
        ? `${l.lane} first-attempt success >= ${p.targets.first_attempt_success_min_pct}%`
        : `${l.lane} on-time >= ${p.targets.lead_time_compliance_min_pct}%`,
    });
  }
  const sev = { high: 0, medium: 1, low: 2 };
  out.sort((a, b) => sev[a.severity] - sev[b.severity] || b.affected.length - a.affected.length);
  return {
    headline: `${p.network.lanes_flagged} of ${p.network.lanes_total} lanes and ${p.network.hubs_flagged} hub(s) flagged.`,
    issues: out,
    watchlist: p.recurring_patterns.map(r => `${r.hub_code} ${r.flow}: weekend median ${r.weekend_dwell_p50_h}h vs weekday ${r.weekday_dwell_p50_h}h (recurring)`),
    summary_th: `พบเส้นทางผิดปกติ ${p.network.lanes_flagged} จาก ${p.network.lanes_total} เส้นทาง และฮับผิดปกติ ${p.network.hubs_flagged} แห่ง (สรุปด้วยกฎอัตโนมัติ)`,
  };
}

// ---------------------------------------------------------------- run
let ai = null, status = 'validated', problems = [], checked = 0;
// Accept both response formats: Claude Messages API (content[]) and Gemini generateContent (candidates[])
let rawText = null;
if (!resp.error && Array.isArray(resp.content)) {
  rawText = resp.content.filter(c => c.type === 'text').map(c => c.text).join('');
} else if (!resp.error && Array.isArray(resp.candidates) && resp.candidates[0]?.content?.parts) {
  rawText = resp.candidates[0].content.parts.map(p => p.text || '').join('');
}
if (rawText === null) {
  status = 'api_error_fallback';
  problems.push('AI API error: ' + JSON.stringify(resp.error || resp).slice(0, 160).replace(/,/g, ';'));
} else {
  const raw = rawText.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { ai = JSON.parse(raw); } catch (e) { problems.push('AI output was not valid JSON'); }
  const v = validate(ai);
  checked = v.checked;
  if (!v.ok) { status = 'rejected_fallback'; problems.push(...v.issues); }
}
const summary = status === 'validated' ? ai : fallbackSummary(payload);
const source = status === 'validated' ? 'claude' : 'rules';

// ---------------------------------------------------------------- format
const n = payload.network;
const icon = { high: '🔴', medium: '🟠', low: '🟡' };
// AI text is plain text: escape Discord markdown characters so a stray "_" or "*"
// (e.g. in a field name like lead_time_compliance_pct) can't turn half the message italic.
const esc = t => String(t == null ? '' : t).replace(/([\\_*~`|>])/g, '\\$1');
const lines = [
  `**LaneWatch · Daily lane health · ${payload.report_date}**`,
  `First-attempt success **${n.first_attempt_success_pct}%** (baseline ${n.first_attempt_success_baseline_pct}%) · On-time **${n.lead_time_compliance_pct}%** (baseline ${n.lead_time_compliance_baseline_pct}%) · ${n.lanes_flagged}/${n.lanes_total} lanes, ${n.hubs_flagged} hub(s) flagged`,
  '',
  `> ${esc(summary.headline)}`,
  '',
];
for (const i of summary.issues) {
  lines.push(`${icon[i.severity] || '⚪'} **${esc(i.title)}**  ${(i.affected || []).map(a => '`' + a + '`').join(' ')}`);
  lines.push(`> ${esc(i.one_liner || i.what_happened)}`);
  lines.push(`• **What:** ${esc(i.what_happened)}`);
  lines.push(`• **Likely cause:** ${esc(i.likely_cause)} (confidence: ${esc(i.confidence)})`);
  lines.push(`• **Action:** ${esc(i.suggested_action)}`);
  lines.push(`• **Track:** ${esc(i.control_metric)}`);
  lines.push('');
}
if (summary.watchlist && summary.watchlist.length) lines.push(`**Watchlist:** ${summary.watchlist.map(esc).join(' · ')}`, '');
if (summary.summary_th) lines.push(`🇹🇭 ${esc(summary.summary_th)}`, '');
lines.push(status === 'validated'
  ? `_AI summary validated: ${checked} numbers checked against source data._`
  : `_⚠️ AI summary not used (${esc(problems.join('; '))}). Showing rule-based summary._`);

const issue_rows = summary.issues.map(i => ({
  report_date: payload.report_date, severity: i.severity, scope: i.scope,
  affected: (i.affected || []).join(', '), title: i.title, one_liner: i.one_liner || i.what_happened, what_happened: i.what_happened,
  likely_cause: i.likely_cause, confidence: i.confidence, suggested_action: i.suggested_action,
  control_metric: i.control_metric, source,
}));
const lane_rows = payload.all_lanes.map(l => ({ report_date: payload.report_date, ...l, severity: l.severity || '' }));

return [{
  json: {
    report_date: payload.report_date,
    message_text: lines.join('\n'),
    summary, ai_status: status, problems,
    issue_rows, lane_rows,
    log: {
      report_date: payload.report_date, dq_pass: true,
      lanes_flagged: n.lanes_flagged, hubs_flagged: n.hubs_flagged,
      ai_status: status, notes: (problems.join('; ') || 'ok').replace(/,/g, ';').slice(0, 500),
    },
  },
}];

// n8n Code node: "All clear" (data passed DQ and nothing was flagged: no need to call Claude)
const { payload } = $input.first().json;
const n = payload.network;
const watch = payload.recurring_patterns
  .map(r => `${r.hub_code} ${r.flow}: weekend median ${r.weekend_dwell_p50_h}h vs weekday ${r.weekday_dwell_p50_h}h`);
const text = [
  `**LaneWatch · Daily lane health · ${payload.report_date}**`,
  `🟢 All ${n.lanes_total} lanes within normal range.`,
  `First-attempt success **${n.first_attempt_success_pct}%** (baseline ${n.first_attempt_success_baseline_pct}%) · On-time **${n.lead_time_compliance_pct}%** (baseline ${n.lead_time_compliance_baseline_pct}%)`,
  watch.length ? `**Watchlist:** ${watch.join(' · ')}` : '',
].filter(Boolean).join('\n');

return [{
  json: {
    report_date: payload.report_date,
    message_text: text,
    issue_rows: [],
    lane_rows: payload.all_lanes.map(l => ({ report_date: payload.report_date, ...l, severity: l.severity || '' })),
    log: { report_date: payload.report_date, dq_pass: true, lanes_flagged: 0, hubs_flagged: 0, ai_status: 'skipped', notes: 'no flags' },
  },
}];

// n8n Code node: "DQ alert" (data-quality gate failed: send an alert, NOT a summary)
const row = $input.first().json;
const checks = typeof row.checks === 'string' ? JSON.parse(row.checks) : row.checks;
const failed = checks.filter(c => !c.ok);
const text = [
  `**LaneWatch · 🚨 Data-quality gate FAILED · ${row.report_date}**`,
  `No performance summary was sent, because it would be built on bad data.`,
  ...failed.map(c => `• **${c.check}**: observed \`${c.observed}\`, expected ${c.rule}`),
  `_Passed: ${checks.filter(c => c.ok).map(c => c.check).join(', ')}_`,
  `Next step: check the upstream feed, reload, then re-run the workflow manually.`,
].join('\n');

return [{
  json: {
    report_date: row.report_date,
    message_text: text,
    issue_rows: [],
    lane_rows: [],
    log: {
      report_date: row.report_date, dq_pass: false, lanes_flagged: 0, hubs_flagged: 0, ai_status: 'skipped',
      notes: failed.map(c => `${c.check}=${c.observed}`).join('; ').slice(0, 500),
    },
  },
}];

// n8n Code node: "Split for Discord"
// Discord rejects messages over 2,000 characters, and the daily summary is usually longer.
// Split on blank lines (between issues) so no issue is cut in half; each item = one Discord message.
const LIMIT = 1900;
const text = $input.first().json.message_text || '';
const blocks = text.split('\n\n');
const chunks = [];
let cur = '';
for (const b of blocks) {
  const piece = cur ? cur + '\n\n' + b : b;
  if (piece.length <= LIMIT) { cur = piece; continue; }
  if (cur) chunks.push(cur);
  if (b.length <= LIMIT) { cur = b; continue; }
  // a single block longer than the limit: fall back to splitting by line, then hard-cut
  cur = '';
  for (const line of b.split('\n')) {
    const p2 = cur ? cur + '\n' + line : line;
    if (p2.length <= LIMIT) { cur = p2; continue; }
    if (cur) chunks.push(cur);
    let rest = line;
    while (rest.length > LIMIT) { chunks.push(rest.slice(0, LIMIT)); rest = rest.slice(LIMIT); }
    cur = rest;
  }
}
if (cur) chunks.push(cur);
return chunks.map((content, i) => ({ json: { content, part: i + 1, parts: chunks.length } }));

// n8n Code node: "Issues today rows"
// Builds the "issues_today" dashboard tab (cleared every run, so it only ever shows today).
//
// FACTS ONLY: every cell is written by code straight from the SQL detection output (the same numbers
// the SQL computed). No AI text appears in this table, so the dashboard can't be biased by the model.
// The AI's explanation and suggested actions go to Discord and the "Issues" history tab instead.
const pick = name => { try { return $(name).first().json; } catch (e) { return null; } };
const fmt = pick('Validate & format') || pick('All clear') || pick('DQ alert');
const req = pick('Build AI request') || pick('Build AI request');
const date = fmt.report_date;
const SEV = { high: '🔴 High', medium: '🟠 Medium', low: '🟡 Low' };

// data-quality gate failed: no payload exists, report that fact only
if (fmt.log && fmt.log.dq_pass === false) {
  return [{ json: { Date: date, Severity: '⚪ n/a', Where: '-', 'What happened': 'Data check failed: data incomplete, no analysis today' } }];
}

const p = req && req.payload;
const lanes = (p && p.lanes_flagged) || [];
const hubs = (p && p.hubs_flagged) || [];
if (lanes.length + hubs.length === 0) {
  return [{ json: { Date: date, Severity: '🟢 OK', Where: 'All lanes', 'What happened': 'All lanes within normal range' } }];
}

// fact from the lanes table: which flagged hubs does this lane pass through?
const flaggedHubs = new Set(hubs.map(h => h.hub_code));
const viaHub = l => [l.origin_hub, l.dest_hub].filter(h => flaggedHubs.has(h));

const rows = [];

// one row per flagged hub (inbound + outbound combined)
const byHub = {};
hubs.forEach(h => { (byHub[h.hub_code] = byHub[h.hub_code] || []).push(h); });
for (const [code, hs] of Object.entries(byHub)) {
  const parts = hs.map(h => `${h.flow} ${h.dwell_p50_h}h (usually ${h.dwell_p50_same_weekday_baseline_h}h)`);
  rows.push({
    sev: 0,
    Severity: SEV.high,
    Where: `${code} hub`,
    'What happened': `Median processing time: ${parts.join(', ')}`,
  });
}

// one row per flagged lane, listing only the KPIs that breached
for (const l of lanes) {
  const k = l.kpis;
  const facts = [];
  if (l.breaches.includes('first_attempt_success'))
    facts.push(`First-attempt success ${k.first_attempt_success_pct}% (usually ${k.first_attempt_success_baseline_pct}%)`);
  if (l.breaches.includes('lead_time_compliance'))
    facts.push(`On-time ${k.lead_time_compliance_pct}% (usually ${k.lead_time_compliance_baseline_pct}%)`);
  rows.push({
    sev: l.severity === 'high' ? 1 : 2,
    Severity: SEV[l.severity] || l.severity,
    Where: l.lane,
    'What happened': facts.join('; ') + viaHub(l).map(h => ` · passes through ${h} hub`).join(''),
  });
}

rows.sort((a, b) => a.sev - b.sev);
return rows.map(({ sev, ...r }) => ({ json: { Date: date, ...r } }));
